<script setup lang="ts">
import { computed, ref } from 'vue';
import { IonContent, IonIcon, IonPage } from '@ionic/vue';
import { addOutline, locationOutline, searchOutline } from 'ionicons/icons';

const search = ref('');
const filter = ref('all');
const notice = ref('');
const spaces = [
  { name: 'Sage House', location: 'Poblacion, Makati', occupancy: '4/5 occupied', price: 7200, views: 184, rating: '4.8', status: 'active', image: 'https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=900&q=85' },
  { name: 'The Greenhouse', location: 'Katipunan, Quezon City', occupancy: '3/4 occupied', price: 8500, views: 236, rating: '4.9', status: 'active', image: 'https://images.unsplash.com/photo-1522708323590-d24dbb6b0267?auto=format&fit=crop&w=900&q=85' },
  { name: 'The Nook Annex', location: 'Taft, Manila', occupancy: 'Not published', price: 5800, views: 0, rating: '—', status: 'draft', image: 'https://images.unsplash.com/photo-1598928506311-c55ded91a20c?auto=format&fit=crop&w=900&q=85' },
];
const filteredSpaces = computed(() => spaces.filter((space) => (filter.value === 'all' || space.status === filter.value) && space.name.toLowerCase().includes(search.value.toLowerCase())));
let noticeTimer: number | undefined;
function showNotice(message: string) { notice.value = message; window.clearTimeout(noticeTimer); noticeTimer = window.setTimeout(() => { notice.value = ''; }, 2500); }
</script>

